<?php

declare(strict_types=1);

namespace App\Tests\Api;

use App\Tests\Support\ContractDocument;
use PHPUnit\Framework\Attributes\Test;
use Symfony\Bundle\FrameworkBundle\Console\Application;
use Symfony\Component\Console\Input\ArrayInput;
use Symfony\Component\Console\Output\BufferedOutput;

/**
 * B-3's phase-2 half — the generated artifact, and API-10a's three outcomes.
 *
 * The spec is regenerated by running the command rather than by reaching into
 * the factory, because **NO ARTIFACT is one of the three outcomes** and a
 * generator that cannot produce a document has to be able to say so here.
 */
final class OpenApiContractTest extends ApiTestCase
{
    /**
     * The write operations this slice authors: four on `/items`, plus
     * `IssueToken`, plus `ChangePassword` (E-23, 2026-09-09), plus **six on
     * `/purchase-orders`** (2026-09-10) — `UpdatePurchaseOrder`,
     * `DeletePurchaseOrder`, `ApprovePurchaseOrder`, `CreatePurchaseOrderLine`,
     * `UpdatePurchaseOrderLine`, `DeletePurchaseOrderLine` — plus **two more on
     * 2026-09-11**, `CreatePurchaseOrder` and `CancelPurchaseOrder`, which is
     * why this number was 14 and not 12 — **and 15 since step 8 (2026-09-11)**,
     * `CreateGoodsReceipt` (`GetGoodsReceipt` is a read). Not a description
     * of the whole contract — it is the anti-vacuity floor: if the `ApiResource`
     * classes are deleted the count drops and this file goes red, which is the
     * second mutation API-10a names.
     *
     * **Both sides of API-10a's comparison moved in that pass and they moved by
     * the same one**, which is the property the VACUOUS branch depends on: the
     * document gained a `ChangePassword` row in §4.2 and the tree gained a
     * `PasswordResource`. Raising this number without authoring the operation
     * would turn the floor into a ceiling nobody can reach; authoring it without
     * raising this number leaves the floor below the truth. Neither is caught by
     * the other test, so both are done here deliberately.
     */
    private const AUTHORED_WRITE_OPERATIONS = 15;

    /** @return array<string, mixed> */
    private function regenerate(): array
    {
        $application = new Application(self::bootedKernel());
        $application->setAutoExit(false);

        // `phpunit.dist.xml` sets SHELL_VERBOSITY=-1, and Symfony's console
        // reads that into VERBOSITY_QUIET -- under which the export command
        // writes nothing at all and the artifact silently disappears. Cleared
        // for the duration of the run so that "the generator produced nothing"
        // means what it says.
        $verbosity = $_SERVER['SHELL_VERBOSITY'] ?? null;
        unset($_SERVER['SHELL_VERBOSITY'], $_ENV['SHELL_VERBOSITY']);
        putenv('SHELL_VERBOSITY');

        $output = new BufferedOutput();

        try {
            $status = $application->run(new ArrayInput(['command' => 'api:openapi:export']), $output);
        } finally {
            if (null !== $verbosity) {
                $_SERVER['SHELL_VERBOSITY'] = $verbosity;
                $_ENV['SHELL_VERBOSITY'] = $verbosity;
                putenv('SHELL_VERBOSITY='.$verbosity);
            }
        }

        self::assertSame(0, $status, 'NO ARTIFACT: the spec could not be generated. API-10a: an absent artifact is not evidence.');

        $spec = json_decode($output->fetch(), true);
        self::assertIsArray($spec, 'NO ARTIFACT: the generator produced something that is not a JSON document.');
        self::assertArrayHasKey('paths', $spec);

        return $spec;
    }

    private static function bootedKernel(): \Symfony\Component\HttpKernel\KernelInterface
    {
        return self::$kernel ?? throw new \LogicException('The kernel is booted in setUp().');
    }

    /**
     * API-10a. The outcome today is **VACUOUS** and this test says so out loud:
     * one resource is authored out of the contract's whole inventory, so the
     * `id` assertion below is real but the gate is not passed.
     *
     * When the remaining resources land, the counts converge and this test goes
     * red — which is deliberate. It is the thing that forces somebody to change
     * the assertion to PASS on purpose rather than discovering that a partially
     * authored spec had been reported as green.
     */
    #[Test]
    public function theApi10aOutcomeIsVacuousAndIsNotRecordedAsAPass(): void
    {
        $spec = $this->regenerate();

        self::assertSame(
            self::AUTHORED_WRITE_OPERATIONS,
            \count($this->writeOperations($spec)),
            'The generated spec no longer declares the write operations this slice authors.',
        );

        if (!ContractDocument::isAvailable()) {
            self::markTestSkipped('docs/API.md is gitignored and absent, so the VACUOUS comparison has no second side. The floor above still ran.');
        }

        $documented = array_filter(
            ContractDocument::operationRows(),
            static fn (array $row): bool => \in_array($row['method'], ['POST', 'PATCH', 'DELETE'], true),
        );

        self::assertGreaterThan(
            self::AUTHORED_WRITE_OPERATIONS,
            \count($documented),
            \sprintf(
                'The spec now declares as many write operations as §4.2 does (%d). The API-10a outcome has moved from '
                .'VACUOUS to PASS/FAIL and this test must be rewritten to assert the PASS branch.',
                \count($documented),
            ),
        );
    }

    /**
     * The `id` assertion itself, which is what B-3's phase-2 check is for. It
     * resolves `$ref`s before inspecting: a schema-local scan misses an `id`
     * inside a referenced component, which is exactly where a nested write
     * would put one.
     *
     * **This proves B-3's declaration layer only** — that no request schema
     * *documents* an `id`. It cannot see whether a body carrying one is
     * accepted; that is `ItemWriteTest::aCreateCarryingAnIdIsRefused`, whose
     * docblock names the three layers and which one answers.
     *
     * Mutation (C5, 2026-09-14, `backend/var/cache/test` deleted before the
     * mutated run and before the revert run — Rule 17): `public ?string $id`
     * added to `CreateItemInput`, with `CreateItem`'s `allow_extra_attributes`
     * also removed → RED, `B-3: a write schema declares a row identifier.` with
     * `POST /api/v1/items application/json /id`. The runtime test stayed GREEN
     * in that same run — API Platform's own normaliser refuses the `id` first
     * (the re-run saw the same with the property alone). Revert: GREEN.
     */
    #[Test]
    public function noWriteSchemaDeclaresAnIdProperty(): void
    {
        $spec = $this->regenerate();
        $writes = $this->writeOperations($spec);

        self::assertNotSame([], $writes, 'No write operation was found, so the assertion below would be vacuous.');

        $inspected = 0;
        $offenders = [];

        foreach ($writes as $label => $operation) {
            foreach ($operation['requestBody']['content'] ?? [] as $mediaType => $content) {
                if (!isset($content['schema'])) {
                    continue;
                }

                ++$inspected;
                foreach ($this->propertyPaths($content['schema'], $spec) as $path) {
                    if (str_ends_with($path, '/id')) {
                        $offenders[] = $label.' '.$mediaType.' '.$path;
                    }
                }
            }
        }

        self::assertGreaterThan(0, $inspected, 'No request schema was inspected, so this check had no subject.');
        self::assertSame([], $offenders, 'B-3: a write schema declares a row identifier.');
    }

    /** API-9, as the artifact states it. */
    #[Test]
    public function everyWriteSchemaRefusesAdditionalProperties(): void
    {
        $spec = $this->regenerate();
        $checked = 0;

        foreach ($this->writeOperations($spec) as $label => $operation) {
            foreach ($operation['requestBody']['content'] ?? [] as $content) {
                $schema = $this->resolve($content['schema'] ?? [], $spec);
                ++$checked;
                self::assertFalse($schema['additionalProperties'] ?? true, $label.' accepts undeclared fields.');
            }
        }

        self::assertGreaterThan(0, $checked);
    }

    /** A `$ref` naming a component that does not exist is a spec that cannot be read. */
    #[Test]
    public function everyReferenceInTheSpecResolves(): void
    {
        $spec = $this->regenerate();

        $refs = [];
        array_walk_recursive($spec, static function (mixed $value, string|int $key) use (&$refs): void {
            if ('$ref' === $key && \is_string($value)) {
                $refs[] = $value;
            }
        });

        self::assertNotSame([], $refs);

        foreach (array_unique($refs) as $ref) {
            self::assertSame('#/components/schemas/', substr($ref, 0, 21), 'Unexpected reference form: '.$ref);
            self::assertArrayHasKey(substr($ref, 21), $spec['components']['schemas'], $ref.' names no component.');
        }
    }

    /** API-2 and API-3, as the artifact states them. */
    #[Test]
    public function theSpecIsMountedAtTheVersionedBasePathAndMentionsNoJsonLd(): void
    {
        $spec = $this->regenerate();

        self::assertNotSame([], $spec['paths']);
        foreach (array_keys($spec['paths']) as $path) {
            self::assertStringStartsWith(self::BASE.'/', (string) $path);
        }

        $encoded = json_encode($spec, \JSON_THROW_ON_ERROR);
        self::assertStringNotContainsString('application/ld+json', $encoded);
        self::assertStringNotContainsString('hydra', $encoded);
    }

    /**
     * API-O-33 option (a): the receipt's `received_by` is advertised as an
     * `ActorReference` **or null**, the same schema `PurchaseOrder.created_by`
     * carries. The column is nullable by design, so a spec that promised an
     * object would promise something the API does not always send.
     */
    #[Test]
    public function theReceiptReadSchemaAdvertisesTheReceiverAsNullableLikeTheCreator(): void
    {
        $spec = $this->regenerate();
        $nullableActor = ['anyOf' => [['$ref' => '#/components/schemas/ActorReference'], ['type' => 'null']]];

        self::assertSame($nullableActor, $spec['components']['schemas']['GoodsReceipt']['properties']['received_by'] ?? null);
        self::assertSame($nullableActor, $spec['components']['schemas']['PurchaseOrder']['properties']['created_by'] ?? null);
    }

    /** §12.3 — every operation declares an explicit `operationId`, and no two share one. */
    #[Test]
    public function everyOperationIdIsExplicitAndUnique(): void
    {
        $spec = $this->regenerate();

        $ids = [];
        foreach ($spec['paths'] as $path => $methods) {
            foreach ($methods as $method => $operation) {
                self::assertArrayHasKey('operationId', $operation, $method.' '.$path);
                self::assertStringStartsNotWith('_api_', $operation['operationId'], 'API Platform\'s derivation was not overridden on '.$method.' '.$path);
                $ids[] = $operation['operationId'];
            }
        }

        self::assertSame($ids, array_unique($ids));
    }

    /**
     * §3.3's phase-1 check, executed rather than described: the two ragged-row
     * guards, the extraction, and the assertion. Part (0b) is here because a
     * real defect walked through part (0a) — a gained cell and a lost trailing
     * pipe cancel exactly, leaving the field count unchanged.
     */
    #[Test]
    public function theContractDocumentDeclaresNoIdOnAnyWriteRow(): void
    {
        if (!ContractDocument::isAvailable()) {
            self::markTestSkipped('docs/API.md is gitignored and absent from this checkout. See the phase-2 report.');
        }

        $fieldCounts = [];
        $delimiterFaults = [];

        foreach (ContractDocument::lines() as $number => $line) {
            $pipes = substr_count($line, '|');
            if ($pipes <= 8) {
                continue;
            }

            $fieldCounts[] = $pipes + 1;

            if (!str_starts_with($line, '|')) {
                continue;
            }
            if (!str_ends_with(rtrim($line), '|')) {
                $delimiterFaults[] = 'line '.($number + 1).': row does not close with a pipe';
            } elseif (10 !== $pipes) {
                $delimiterFaults[] = 'line '.($number + 1).': wrong pipe count ('.$pipes.')';
            }
        }

        // (0a) one field count and nothing else.
        self::assertSame([11], array_values(array_unique($fieldCounts)));
        // (0b) delimiter integrity, on the literal bytes.
        self::assertSame([], $delimiterFaults);

        // (1) the extraction must be non-empty, and that is half the check.
        $writes = array_filter(
            ContractDocument::operationRows(),
            static fn (array $row): bool => \in_array($row['method'], ['POST', 'PATCH', 'DELETE'], true),
        );
        self::assertNotSame([], $writes);

        // (2) no write row accepts a field named `id`. `supplier_id` and
        // `role_id` are §3.1 case 1 and must NOT match.
        $offenders = [];
        foreach ($writes as $operationId => $row) {
            if (1 === preg_match('/`id`|\.id`/', $row['accepts'])) {
                $offenders[] = $operationId;
            }
        }

        self::assertSame([], $offenders);
    }

    /**
     * @param array<string, mixed> $spec
     *
     * @return array<string, array<string, mixed>>
     */
    private function writeOperations(array $spec): array
    {
        $writes = [];

        foreach ($spec['paths'] as $path => $methods) {
            foreach ($methods as $method => $operation) {
                if (\in_array(strtolower((string) $method), ['post', 'patch', 'delete'], true)) {
                    $writes[strtoupper((string) $method).' '.$path] = $operation;
                }
            }
        }

        return $writes;
    }

    /**
     * @param array<string, mixed> $schema
     * @param array<string, mixed> $spec
     *
     * @return array<string, mixed>
     */
    private function resolve(array $schema, array $spec): array
    {
        if (isset($schema['$ref']) && \is_string($schema['$ref'])) {
            $name = substr($schema['$ref'], 21);

            return $spec['components']['schemas'][$name] ?? [];
        }

        return $schema;
    }

    /**
     * Every property path a schema declares, with `$ref`s followed.
     *
     * @param array<string, mixed> $schema
     * @param array<string, mixed> $spec
     * @param list<string>         $seen
     *
     * @return list<string>
     */
    private function propertyPaths(array $schema, array $spec, string $prefix = '', array $seen = []): array
    {
        if (isset($schema['$ref']) && \is_string($schema['$ref'])) {
            if (\in_array($schema['$ref'], $seen, true)) {
                return [];
            }
            $seen[] = $schema['$ref'];
        }

        $schema = $this->resolve($schema, $spec);
        $paths = [];

        foreach ($schema['properties'] ?? [] as $name => $property) {
            $here = $prefix.'/'.$name;
            $paths[] = $here;
            if (\is_array($property)) {
                $paths = [...$paths, ...$this->propertyPaths($property, $spec, $here, $seen)];
            }
        }

        foreach (['items', 'additionalProperties'] as $nested) {
            if (\is_array($schema[$nested] ?? null)) {
                $paths = [...$paths, ...$this->propertyPaths($schema[$nested], $spec, $prefix.'/[]', $seen)];
            }
        }

        foreach (['anyOf', 'oneOf', 'allOf'] as $composite) {
            foreach ($schema[$composite] ?? [] as $branch) {
                if (\is_array($branch)) {
                    $paths = [...$paths, ...$this->propertyPaths($branch, $spec, $prefix, $seen)];
                }
            }
        }

        return $paths;
    }
}
